#define ROWS 1024
#define COLS 1024
int matrix[ROWS][COLS];

// C/C++: Row-Major Order (Rows stored contiguously)

// Cache Efficient (Accessing elements in memory order)
for (int r = 0; r < ROWS; r++) {
    for (int c = 0; c < COLS; c++) {
        matrix[r][c] += 1; // 'c' changes fastest (stride = 1)
    }
}

// Cache Inefficient (Forces large memory strides)
for (int c = 0; c < COLS; c++) {
    for (int r = 0; r < ROWS; r++) {
        matrix[r][c] += 1; // 'r' changes fastest (stride = COLS)
    }
}

// Pointer arithmetic equivalent:
int* p = &matrix[0][0];
p[ROWS * c + r] = 42; // Low-level address calc
